using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Text;using System.Web.Script.Serialization;using System.Windows.Forms;
internal sealed class CloudPetAsset {public string id{get;set;}public string name{get;set;}public string url{get;set;}public string sha256{get;set;}public long bytes{get;set;}}
internal sealed class CloudPetCatalog {public int schema{get;set;}public CloudPetAsset[] pets{get;set;}public CloudPetAsset[] previews{get;set;}}
internal static class CloudPets {
    internal static string Preview(string root,string state,string id){var data=new JavaScriptSerializer().Deserialize<CloudPetCatalog>(File.ReadAllText(Path.Combine(root,"cloud-pets.json")));var item=data==null||data.schema!=1||data.previews==null?null:data.previews.SingleOrDefault(p=>p.id==id);if(item==null||item.id!="bailong"||!SoftwareUpdate.Digest(item.sha256)||item.bytes<1||item.bytes>2*1024*1024)throw new InvalidDataException("形象预览清单无效。");var uri=new Uri(item.url);if(uri.Scheme!="https"||uri.Host!="raw.githubusercontent.com"||!uri.AbsolutePath.StartsWith("/Wunsch2048/codex-bailong-desktop-pet/",StringComparison.Ordinal)||!uri.AbsolutePath.EndsWith(".png",StringComparison.Ordinal))throw new InvalidDataException("形象预览来源无效。");string folder=Path.Combine(state,"pet-previews");Directory.CreateDirectory(folder);string path=Path.Combine(folder,id+"-"+item.sha256.Substring(0,12)+".png");if(File.Exists(path)&&new FileInfo(path).Length==item.bytes&&SoftwareUpdate.Hash(path).Equals(item.sha256,StringComparison.OrdinalIgnoreCase))return path;string temporary=path+".partial-"+Guid.NewGuid().ToString("N");try{ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(uri);request.UserAgent="CodexHub-PetPreview";request.Timeout=request.ReadWriteTimeout=15000;using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=File.Create(temporary)){long total=0;int count;byte[] buffer=new byte[32768];while((count=input.Read(buffer,0,buffer.Length))>0){total+=count;if(total>item.bytes)throw new InvalidDataException("形象预览大小无效。");output.Write(buffer,0,count);}if(total!=item.bytes)throw new InvalidDataException("形象预览下载不完整。");}if(!SoftwareUpdate.Hash(temporary).Equals(item.sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("形象预览校验失败。");if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);return path;}finally{if(File.Exists(temporary))File.Delete(temporary);}}
    public static CloudPetAsset Asset(string root,string id){var data=new JavaScriptSerializer().Deserialize<CloudPetCatalog>(File.ReadAllText(Path.Combine(root,"cloud-pets.json")));var asset=data==null||data.schema!=1||data.pets==null?null:data.pets.SingleOrDefault(p=>p.id==id);if(asset==null||asset.id!="deepseek-fat-fish"||!SoftwareUpdate.Digest(asset.sha256)||asset.bytes<1||asset.bytes>256L*1024*1024)throw new InvalidDataException("云端宠物清单无效。");SoftwareUpdate.ReleaseUri(asset.url);return asset;}
    public static string Obtain(string root,string state,string id,Action<string> progress,Func<bool> cancel){
        var asset=Asset(root,id);string downloads=Path.Combine(state,"pet-downloads");Directory.CreateDirectory(downloads);string archive=Path.Combine(downloads,id+"-"+asset.sha256.Substring(0,12)+".zip");
        if(!File.Exists(archive)||new FileInfo(archive).Length!=asset.bytes||!SoftwareUpdate.Hash(archive).Equals(asset.sha256,StringComparison.OrdinalIgnoreCase)){
            string partial=archive+".partial-"+Guid.NewGuid().ToString("N");try{ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(asset.url);request.UserAgent="CodexHub-Pets";request.Timeout=request.ReadWriteTimeout=30000;using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=File.Create(partial)){var buffer=new byte[65536];long total=0,last=-250;var clock=Stopwatch.StartNew();int read;while((read=input.Read(buffer,0,buffer.Length))>0){if(cancel())throw new OperationCanceledException();total+=read;if(total>asset.bytes)throw new InvalidDataException("宠物下载超出清单大小。");output.Write(buffer,0,read);if(clock.ElapsedMilliseconds-last>=250){last=clock.ElapsedMilliseconds;progress("正在下载 "+asset.name+" "+(total*100/asset.bytes)+"%");}}if(total!=asset.bytes)throw new InvalidDataException("宠物下载不完整。");}if(!SoftwareUpdate.Hash(partial).Equals(asset.sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("宠物包校验失败。");if(File.Exists(archive))File.Replace(partial,archive,null);else File.Move(partial,archive);}finally{if(File.Exists(partial))File.Delete(partial);}
        }
        string stage=Path.Combine(state,"pet-imports",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{Extract(archive,stage,cancel);PetPack.Read(stage,false);return stage;}catch{PetImporter.DeleteStage(stage,state);throw;}
    }
    internal static void Extract(string archive,string stage,Func<bool> cancel){long total=0;var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>512)throw new InvalidDataException("宠物包条目过多。");foreach(var entry in zip.Entries){if(cancel())throw new OperationCanceledException();string name=entry.FullName.Replace('\\','/');if(name.EndsWith("/"))continue;if(!names.Add(name)||name.StartsWith("/")||name.Contains(":")||name.Split('/').Any(p=>p==".."||p=="."||p.Length==0)||((entry.ExternalAttributes>>16)&0xf000)==0xa000||entry.Length>32L*1024*1024||(total+=entry.Length)>384L*1024*1024)throw new InvalidDataException("宠物包路径或大小无效。");string extension=Path.GetExtension(name).ToLowerInvariant();if(!new[]{".json",".png",".webm",".wav"}.Contains(extension)&&Path.GetFileName(name)!="LICENSE")throw new InvalidDataException("宠物包包含不支持的文件。");string target=Path.GetFullPath(Path.Combine(stage,name));if(!target.StartsWith(Path.GetFullPath(stage).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("宠物包超出目录。");Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew))input.CopyTo(output);}}}
}
internal static class PetMediaRuntime {
    static string cached;
    public static string Find(){if(cached!=null&&File.Exists(cached))return cached;string root=AppDomain.CurrentDomain.BaseDirectory,packaged=Path.Combine(root,@"engine\runtime\ffmpeg\ffmpeg.exe");if(File.Exists(packaged))return cached=packaged;var spec=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,@"engine\assets\ffmpeg-runtime.json")));string hash=Convert.ToString(spec["sha256"]);string directory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexDreamSkin","runtime","ffmpeg-"+hash.Substring(0,16)),marker=Path.Combine(directory,"runtime.json"),exe=Path.Combine(directory,"ffmpeg.exe");if(File.Exists(exe)&&File.Exists(marker)){var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(marker));if(Convert.ToString(data["archiveSha256"])==hash)return cached=exe;}throw new FileNotFoundException("透明动画解码器尚未准备，请在宠物页面点击下载该形象后重试。");}
}
internal sealed partial class Manager {
    void LoadPetCardPreview(PetCard tile){System.Threading.ThreadPool.QueueUserWorkItem(delegate{System.Drawing.Bitmap picture=null;try{string file=CloudPets.Preview(root,stateDirectory,tile.Pack.Id);using(var source=System.Drawing.Image.FromFile(file)){if(source.Width>2048||source.Height>2048)throw new InvalidDataException("形象预览尺寸无效。");picture=new System.Drawing.Bitmap(source);}var ready=picture;try{BeginInvoke((MethodInvoker)delegate{if(IsDisposed||tile.IsDisposed)ready.Dispose();else tile.SetPoster(ready);});picture=null;}catch(InvalidOperationException){}}catch(Exception){Ui(delegate{if(!tile.IsDisposed){tile.PreviewUnavailable=true;tile.Invalidate();}});}finally{if(picture!=null)picture.Dispose();}});}
    void SelectPreparedPet(PetPack pack){if(pack.Format!="transparent-video-set"){pets.Select(pack);return;}try{PetMediaRuntime.Find();pets.Select(pack);return;}catch(FileNotFoundException){}if(petImporting||updatingSoftware)return;petImporting=true;importButton.Enabled=false;previewHint.Text="动画已内置，首次播放正在准备通用组件；现有宠物继续运行…";ImportWork.Start(delegate{try{PreparePetPlayback();Ui(delegate{pets.Select(pack);previewHint.Text="播放组件已就绪，之后直接复用。";});}catch(Exception error){Ui(delegate{previewHint.Text="播放组件未能准备："+error.Message;});}finally{Ui(delegate{petImporting=false;petImportProgress=null;importButton.Enabled=true;});}});}
    void PreparePetPlayback(){var info=new ProcessStartInfo(Path.Combine(root,@"engine\runtime\node\node.exe"),PetCommandQuote(Path.Combine(root,@"engine\scripts\prepare-media-runtime.mjs"))+" "+PetCommandQuote(stateDirectory)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};PetProcessScope scope;lock(petImportGate){if(cancelPetImport)throw new OperationCanceledException();scope=petImportProcess=new PetProcessScope(info,true);}using(scope){var error=scope.Process.StandardError.ReadToEndAsync();string line;while((line=scope.Process.StandardOutput.ReadLine())!=null)if(line.StartsWith("DREAM_PROGRESS:"))petImportProgress=line.Substring(15);scope.Process.WaitForExit();if(scope.Process.ExitCode!=0)throw new IOException(error.Result.Trim());}lock(petImportGate){if(petImportProcess==scope)petImportProcess=null;}if(cancelPetImport)throw new OperationCanceledException();
    }
    void ImportCloudPet(string id){if(petImporting||pets==null||updatingSoftware)return;petImporting=true;importButton.Enabled=false;previewHint.Text="正在准备云端宠物，已有宠物继续运行…";
        ImportWork.Start(delegate{string stage=null;try{stage=CloudPets.Obtain(root,stateDirectory,id,message=>petImportProgress=message,()=>cancelPetImport);PreparePetPlayback();string destination=Path.Combine(stateDirectory,"pets",id);Directory.CreateDirectory(Path.GetDirectoryName(destination));if(Directory.Exists(destination))throw new IOException("该形象的本地副本已存在，请重新选择。");Directory.Move(stage,destination);stage=null;var pack=PetPack.Read(destination,false);Ui(delegate{pets.Reload();BuildPetCards();pets.Select(pack);previewHint.Text="已下载："+pack.Name+"，之后无需重复下载。";});}catch(Exception error){Ui(delegate{previewHint.Text="宠物下载未完成："+error.Message;});}finally{if(stage!=null)PetImporter.DeleteStage(stage,stateDirectory);Ui(delegate{petImporting=false;petImportProgress=null;importButton.Enabled=true;});}});
    }
}
